```hcl
# File: versions.tf
# Pin Terraform and the AWS provider to exact-enough versions so every
# engineer and the CI runner behave identically. Open ranges cause drift.
terraform {
  required_version = ">= 1.6.0, < 2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
    }
  }
}

provider "aws" {
  region = var.aws_region
}
```

```hcl
# File: variables.tf
# These are the inputs. staging and production pass different values,
# so the SAME code produces consistent-but-sized environments.
variable "aws_region" {
  type        = string
  description = "AWS region for National Bank of India ledger infra"
  default     = "ap-south-1"
}

variable "environment" {
  type        = string
  description = "staging or production"
}

variable "db_instance_class" {
  type        = string
  description = "RDS instance size, e.g. db.t3.medium (staging) or db.r6g.large (prod)"
}

variable "db_allocated_storage" {
  type        = number
  description = "Storage in GB for the ledger database"
}

variable "backup_retention_days" {
  type        = number
  description = "How many days of automated backups to keep"
}
```

```hcl
# File: main.tf
# The desired end state. Terraform computes the API calls to reach it.

# The PostgreSQL ledger database that stores every account balance.
resource "aws_db_instance" "ledger" {
  identifier              = "nbi-ledger-${var.environment}"
  engine                  = "postgres"
  engine_version          = "15.5"
  instance_class          = var.db_instance_class
  allocated_storage       = var.db_allocated_storage
  db_name                 = "ledgerdb"
  username                = "ledger_app"
  # In real life this comes from a secrets manager, never hardcoded.
  manage_master_user_password = true
  backup_retention_period = var.backup_retention_days
  storage_encrypted       = true      # bank data must be encrypted at rest
  deletion_protection     = var.environment == "production" ? true : false
  skip_final_snapshot     = var.environment == "production" ? false : true

  tags = {
    Application = "account-ledger-service"
    Environment = var.environment
    Owner       = "platform-team"
  }
}

# Audit bucket for daily balance-snapshot files.
resource "aws_s3_bucket" "balance_snapshots" {
  bucket = "nbi-balance-snapshots-${var.environment}"

  tags = {
    Application = "account-ledger-service"
    Environment = var.environment
  }
}

# Snapshots must never be publicly readable — it is customer money data.
resource "aws_s3_bucket_public_access_block" "snapshots_block" {
  bucket                  = aws_s3_bucket.balance_snapshots.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
```

```hcl
# File: outputs.tf
# Values exported after apply. The Java service reads the DB endpoint from here.
output "ledger_db_endpoint" {
  value       = aws_db_instance.ledger.endpoint
  description = "Host:port the ledger service connects to"
}

output "snapshot_bucket_name" {
  value       = aws_s3_bucket.balance_snapshots.bucket
  description = "Bucket where daily balance snapshots are written"
}
```

