package com.bank.ledger.config;

import com.zaxxer.hikari.HikariDataSource;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import javax.sql.DataSource;

// The service reads the endpoint that Terraform produced as an output and
// injected into the environment. The app never hardcodes infrastructure.
@Configuration
public class DataSourceConfig {

    // Populated from TF output "ledger_db_endpoint" via the deploy pipeline.
    @Value("${LEDGER_DB_ENDPOINT}")
    private String ledgerDbEndpoint;

    @Bean
    public DataSource ledgerDataSource(@Value("${DB_PASSWORD}") String password) {
        HikariDataSource ds = new HikariDataSource();
        ds.setJdbcUrl("jdbc:postgresql://" + ledgerDbEndpoint + "/ledgerdb");
        ds.setUsername("ledger_app");
        ds.setPassword(password);
        ds.setMaximumPoolSize(15);
        return ds;
    }
}
